content:
V1_R_13_R {
    @ Single vias stacked by more than 4 layers are not allowed. (n=1-3)<= 4
    X = V1N_M INTERACT (V2N_M INTERACT (V3N_M INTERACT (V4N_M INTERACT V5N_M)))
    X NOT INSIDE EXCLU
}

DG_W_1a {
@ DG width >= 0.44um
  (INT DG < 0.44 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

M1DUMCK_S_3c {
    @ Space between dummy metal and Mn pattern(for MnDUMCK.W.1c)>= 0.3um
    (EXT M1DUM_min M1 < 0.3 ABUT<90 SINGULAR REGION INSIDE ALSO) NOT INSIDE EXCLU
}

DFM_S_103_V3 {
    @ Space between Vn and unconnected Mn+1 (n = 1,2,3,4,5,6,7)>= 0.12um
    (EXT M4_EMPTY4 V3_EMPTY4 < 0.12 ABUT<90 REGION OPPOSITE MEASURE ALL NOT CONNECTED) NOT INSIDE EXDFM
}

DFM_S_82 {
@ Space between SABs >= 0.43um
  (EXT SAB < 0.43 ABUT<90 SINGULAR REGION) NOT INSIDE EXDFM
}

SRAA_S_7 {
@ Space between NW and P+AA inside PW>= 0.12 0.11um
  X = EXT NW (PACT INSIDE PW) < 0.11 ABUT<90 SINGULAR REGION
  (X NOT OUTSIDE INST) NOT INSIDE EXCLU
}

HRP_EN_4 {
@ HRP enclosure of high resistance poly>= 0.2um
  (ENC HRP_resistor HRP < 0.20 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLU
}

SRCK_R_19_AA {
    @ No AA/GT/Metal dummy patterns are allowed inside MARKS covered areas.
    (AADUM AND MARKS) NOT INSIDE EXCLUi
}

DFM_S_60 {
@ Space between AA and GT on STI (when channel width<0.15um). DRC waive check the INDMY and INST covered region.>= 0.1um
  GT_check = GT WITH EDGE (LENGTH GATE_W < 0.15)
  X = EXT AA GT_check < 0.1 ABUT<90 SINGULAR REGION
  ((X INSIDE STI) NOT INSIDE (INST OR INDMY)) NOT INSIDE EXDFM
}

RESP1_R_2 {
@ For non-silicide poly resistor, make sure the poly be covered by SAB and implanted by either SN or SP.
  X = GTR INTERACT SAB
  (X NOT (SN OR SP)) NOT INSIDE EXCLU
}

BCB2_W_1_R_6 {
    @ BCB2_W_1: BCB2 width (suggest to consult with package vendor)>= 10um
    @ BCB2_R_6: DRC allows 0.002um checking tolerance in INDMY region for BCB2.W.1-BCB2.S.4 rules.
    ((INT BCB2 < 10 ABUT<90 SINGULAR REGION) NOT INDMY)NOT INSIDE EXCLU
    ((INT BCB2 < 10 - 0.002 ABUT<90 SINGULAR REGION) AND INDMY)NOT INSIDE EXCLU
}

RDL_S_3_R_6 {
@ RDL_S_3:  Space between RDL and L mark window>= 10um
@ RDL_R_6:  DRC allows 0.002um checking tolerance in INDMY region for RDL.W.1-RDL.S.5 rules.
  ((EXT RDL LOGO < 10 ABUT<90 SINGULAR REGION) NOT INDMY) NOT INSIDE EXCLU
  ((EXT RDL LOGO < 10 - 0.002 ABUT<90 SINGULAR REGION) AND INDMY) NOT INSIDE EXCLU
}

SP_EN_9b_R {
@ P+ AA enclosure by SP in NW, except the INST region.>= 0.12um
  X = (PACT NOT COIN EDGE NACT) NOT COIN EDGE SN
  (((ENC X SP < 0.12 ABUT<90 REGION) INSIDE NW) NOT INSIDE INST) NOT INSIDE EXCLU
}

LOGO_S_1_G_TKM {
    @ Space between LOGO and AA, GT or Metal.>= 10um
    (EXT LOGO TKM < 10 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

ESD_W_14c_G {
@ Total channel width of 1.2V ESD Cascoded NMOS for HBM 8KV.>= 720um
X = NET AREA RATIO ENMOS_D_temp_EMPTY2 ESD3C_EMPTY2 [AREA(ESD3C_EMPTY2)/0.002] < 720
((X INTERACT ENGATE)AND 1_2V_ESD_CASCODED) NOT INSIDE EXCLU
}

SRCK_S_6_V5 {
    @ Space between two Vn (n=1~7) slots >= 1.805um
    (EXT V5S_SL < 1.805 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

DFM_S_103_V4 {
    @ Space between Vn and unconnected Mn+1 (n = 1,2,3,4,5,6,7)>= 0.12um
    (EXT M5_EMPTY4 V4_EMPTY4 < 0.12 ABUT<90 REGION OPPOSITE MEASURE ALL NOT CONNECTED) NOT INSIDE EXDFM
}

SRCK_R_18_AA {
    @ No patterns (AA/GT/METAL/RDL) are allowed inside assembly isolation areas
    (AND ISOLATION AA) NOT INSIDE EXCLUi
}

PSUB_A_13 {
    @ PSUB area >= 0.3um2
    (AREA PSUB < 0.3) NOT INSIDE EXCLU
}

RESP1_R_4_R {
@ Dog-bone design at the end of non-silicide poly resistor for contact pick-up is not suggested.
  X = GTR INTERACT SAB
  (CONVEX EDGE X ==1) NOT INSIDE EDGE EXCLU
}

M2_EN_5 {
    @ Enclosed area by Mn >= 0.12 um 2
    X = (HOLES M2 INNER) NOT M2
    (AREA X < 0.12) NOT INSIDE EXCLU
}

DFM_EX_78 {
@ SP extension outside of PMOS AA along GATE poly length direction, if the distance to the related poly is larger than 0.20Âµm. (except the SRAM region)>= 0.13um
  X = PMOS TOUCH EDGE AAEIGT
  Y = ENC X SP < 0.13 ABUT<90 REGION
  (Y NOT INSIDE INST) NOT INSIDE EXDFM
}

LVP_A_8a {
@ LVP area >= 0.122um2
  (AREA LVP < 0.122) NOT INSIDE EXCLU
}

SL_W_L_1_2_M6_G {
    @ SL_W_1_G: Slot width >= 0.8um
    @ SL_L_2_G: Slot length >= 1um
    (NOT RECTANGLE M6SLOT >= 0.8 BY >= 1.0) NOT INSIDE EXCLU
}

M5DUMCK_S_2 {
    @ Space between two Dummy metals>= 0.25um
    (EXT M5DUM < 0.25 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

M6_A_4 {
    @ Mn area (If n=2, DRC waive check the INST region).>= 0.035 um 2
    X = AREA M6 < 0.035
    X NOT INSIDE EXCLU
}

RESNWAA_EN_2 {
@ AA enclosure of NW-Resistor>= 0.3um
 (ENC NWAA_resistor (AA ENCLOSE NWAA_resistor) < 0.3 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

GT_EX_9a_SN {
    @ SN and SP extension outside of poly resistor. Poly resistor enclosed by SN/SP. DRC waive check the INST covered region.>= 0.15um
    ((ENC (GT AND RESP1) SN < 0.15 ABUT<90 SINGULAR REGION) NOT INSIDE INST) NOT INSIDE EXCLU
}

RV_S_3_R_4 {
    @ RV_S_3: Space between two RV >= 3um
    @ RV_R_4: DRC allows 0.002um checking tolerance in INDMY region for RV.EN.1~RV.S.3/ RV.EN.1(R)~RV.S.3(R) rules.
    ((EXT RV < 3 ABUT<90 SINGULAR REGION) NOT INDMY) NOT INSIDE EXCLU
    ((EXT RV < 3 - 0.002 ABUT<90 SINGULAR REGION) AND INDMY) NOT INSIDE EXCLU
}

SN_S_5 {
@ Space between SN and PMOS GATE along source/drain direction, except the INST region>= 0.24um
  X = GATE_W INSIDE EDGE SP
  Y = EXT X SN < 0.24 ABUT<90 OPPOSITE  REGION
  (Y NOT INSIDE INST) NOT INSIDE EXCLU
}

SL_EN_5_M1_G {
    @ Open slot must be fully enclosed by metal line.>= 2um
    (ENC M1SLOT M1i < 2.0 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
    (M1SLOT NOT M1i) NOT INSIDE EXCLU
}

VTNH_EN_4 {
@ VTNH extension outside of MOS AA along GATE poly length direction (except the SRAM region).>= 0.12um
  X = (NACT AND VTNH) TOUCH EDGE GATE
  Y = ENC X VTNH < 0.12 ABUT<90 OPPOSITE REGION
  (Y NOT INSIDE INST) NOT INSIDE EXCLU
 }

HRP_R_10 {
@ Dummy layer "HRPDMY" is marker layer for LVS/ DRC to define high resistance poly resistor region.
  SAB_HRP = SAB INTERACT HRP
  (SAB_HRP NOT INTERACT HRPDMY) NOT INSIDE EXCLU
}

SRCT_S_4a {
@ Space between GATE and contact on AA for 1.2V>= 0.05 0.038um
  X = EXT GATE_M (CT AND AA) < 0.038 ABUT<90 SINGULAR REGION
  ((X NOT DG) NOT OUTSIDE INST) NOT INSIDE EXCLU
}

DUP_R_6_G {
    @ For one top metal process: TV-1 pattern is not allowed under the DUP pad opening area.
    @ For two top metal process: TV1 patterns are not allowed under the DUP pad opening area.
    (DUP_padarea AND V5) NOT INSIDE EXCLU
}

SRCK_W_32_V4 {
    @ Square V1-V7 size = 0.09um
    (NOT RECTANGLE V4S_SQ == 0.09 BY == 0.09) NOT INSIDE EXCLUi
}

M4DUMCK_S_3a {
    @ Space between dummy metal and Mn pattern(for MnDUMCK.W.1a)>= 10um
    (EXT M4DUM_max M4 < 10 ABUT<90 SINGULAR REGION INSIDE ALSO) NOT INSIDE EXCLU
}

SRCK_R_19_TKM {
    @ No AA/GT/Metal dummy patterns are allowed inside MARKS covered areas.
    (TKMDUM AND MARKS) NOT INSIDE EXCLUi
}

SRCK_W_43_M2 {
    @ Metal width of die corner dummy pattern for M1 to M8>= 0.555um
    (INT (M2 AND Die_corner) < 0.555 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

M1DUMCK_S_3b {
    @ Space between dummy metal and Mn pattern(for MnDUMCK.W.1b)>= 3um
    (EXT M1DUM_mid M1 < 3 ABUT<90 SINGULAR REGION INSIDE ALSO) NOT INSIDE EXCLU
}

VTNH_S_7a {
@ Space between VTNH and GATE of other device along other deviceâs source/drain direction>= 0.16um
  X = (GT INSIDE EDGE (AA NOT VTNH)) COIN EDGE GATE
  (EXT X VTNH < 0.16 ABUT<90 REGION OPPOSITE) NOT INSIDE EXCLU
}

M4DUMCK_EN_10 {
    @ Chip edge(BORDER) enclosure of dummy metal>= 2.5um
    (ENC M4DUM BORDER < 2.5 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
    (M4DUM NOT BORDER) NOT INSIDE EXCLU
}

RDL_S_4_R_6 {
@ RDL_S_4:  Space between RDL and fuse area (marked by MARKF)>= 10um
@ RDL_R_6:  DRC allows 0.002um checking tolerance in INDMY region for RDL.W.1-RDL.S.5 rules.
  ((EXT RDL MARKF < 10 ABUT<90 SINGULAR REGION) NOT INDMY) NOT INSIDE EXCLU
  ((EXT RDL MARKF < 10 - 0.002 ABUT<90 SINGULAR REGION) AND INDMY) NOT INSIDE EXCLU
}

ESD_S_5_G {
@ Space from poly edge to CT edge on source side (SCP) for NMOS and PMOS (Fig.2).>= 0.25um
(EXT EGATE_W ECT_S < 0.25 ABUT< 90 REGION) NOT INSIDE EXCLU
}

LOGO_S_1_G_M2 {
    @ Space between LOGO and AA, GT or Metal.>= 10um
    (EXT LOGO M2 < 10 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SN_A_11a {
@ SN enclosed area >= 0.1um2
  (AREA ((HOLES SN INNER) NOT SN) < 0.10 ) NOT INSIDE EXCLU
}

SRCK_S_47 {
    @ Contact distance from each other in die corner dummy area>= 1.021um
    (EXT (CTS_SQ AND Die_corner) < 1.021 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

LOGO_S_1_G_M6 {
    @ Space between LOGO and AA, GT or Metal.>= 10um
    (EXT LOGO M6 < 10 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SP_S_4 {
@ Space between SP and N+ AA inside N well>= 0.02um
  X = NTAP NOT TOUCH EDGE PACT
  Y = X NOT TOUCH EDGE SP
  (EXT SP Y < 0.02 ABUT<90 REGION) NOT INSIDE EXCLU
}

GT_W_14 {
    @ Width of 45 degree GT on STI>= 0.19um
    GT_CHECK = GT INSIDE STI
    X = ANGLE GT_CHECK >= 44.9 <= 45.1
    (INT X < 0.19 ABUT<90 REGION) NOT INSIDE EXCLU
}

RV_EN_1_R_R_4 {
    @ RV_EN_1_R: RV edge fully enclosure by TM2/TKM directly underneath RV>= 1.5um
    @ RV_R_4: DRC allows 0.002um checking tolerance in INDMY region for RV.EN.1~RV.S.3/ RV.EN.1(R)~RV.S.3(R) rules.
    ((ENC RV TKM < 1.50 ABUT<90 SINGULAR REGION OUTSIDE ALSO) NOT INDMY) NOT INSIDE EXCLU
    ((ENC RV TKM < 1.50 - 0.002 ABUT<90 SINGULAR REGION OUTSIDE ALSO) AND INDMY) NOT INSIDE EXCLU
}

M4DUMCK_S_7 {
    @ Space between dummy metal and LOGO.
    @ Metal dummy pattern insertion is not allowed to touch areas covered by LOGO.>= 0.1um
    (EXT M4DUM LOGO < 0.1 ABUT<90 SINGULAR REGION INSIDE ALSO) NOT INSIDE EXCLU
}

LD_W_14_G {
@ LDMOS drain side AA width>= 0.21um
  X = (AA NOT GT) TOUCH STIDMY
  ((INT X < 0.21 ABUT < 90 SINGULAR REGION)NOT INSIDE NOSHR) NOT INSIDE EXCLU
}

PEFU_EN_4a_G {
@ Poly Efuse element must be fully covered by SP.
@ Poly Efuse element enclosure by SP.>= 0.5um
(ENC EFUSE_element SP < 0.5 ABUT < 90 SINGULAR REGION OUTSIDE ALSO)NOT EXCLU
}

PSUB_S_4 {
    @ Space between two PSUBs >= 0.36um
    (EXT PSUB < 0.36 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SRM2_A_4 {
@ M2 area >= 0.03um2
  X = AREA (M2 OR M2DUM) < 0.03
  (X NOT OUTSIDE INST) NOT INSIDE EXCLU
}

RESP1_EX_8 {
@ Extension of SAB outside of non-silicide poly resistor area(follow SAB.EX.6 rule)>= 0.2um
  (ENC GTR SAB < 0.2 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLU
}

V2_S_2a1 {
    @ Space between two Vns >= 0.1um
    (EXT V2 < 0.1 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SRCK_S_36_V5 {
    @ Space between square Vn (n=1~7) >= 0.543um
    (EXT V5S_SQ < 0.543 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

SAB_W_1a {
@ SAB width >= 0.36um
  (INT SAB < 0.36 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

V1_S_2a1 {
    @ Space between two V1s >= 0.1um
    (EXT V1 < 0.1 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SAB_EX_3 {
@ Extension of AA outside of SAB>= 0.2um
  (ENC SAB AA < 0.2 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

LD_S_6_G {
@ Space between one LDMOS gate poly to another LDMOS gate poly on source side>= 0.27um
((EXT (GT INSIDE EDGE LDAA) < 0.27 REGION)NOT INSIDE NOSHR) NOT INSIDE EXCLU
}

AA_S_5c {
    @ Space between NW and N+AA inside 2.5V PW except NW resistor region>= 0.25um
    (EXT (NW NOT INTERACT RESNW) (NACT INSIDE MVPW) < 0.25 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

VTNH_S_2 {
@ Space between two VTNHs. Single-point-interaction is allowed.>= 0.18um
  (EXT VTNH < 0.18 ABUT<90 OPPOSITE REGION) NOT INSIDE EXCLU
}

SRGT_EX_6 {
@ Extension of GATE poly end-cap outside of AA, except small jogs (jog <= 0.005um)>= 0.068um
  X = GATE COIN EDGE AA
  Y = ENC X GT < 0.068 ABUT<90 REGION
  (Y NOT OUTSIDE INST) NOT INSIDE EXCLU
}

DG_O_10a {
@ Overlap of DG and NW, set the value to 0 if it is smaller than 0.36um>= 0.36um
  (INT DG NW > 0 < 0.36 ABUT>0<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SRCK_W_21 {
    @ Passivation slot width (BCB1 is recommended as drawn layer) in MARKS covered areas>= 2.778um
    (INT BCB1S < 2.778 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

ESD_S_5_G {
@ Space from poly edge to CT edge on source side (SCP) for NMOS and PMOS (Fig.2).>= 0.25um
(EXT EGATE_W ECT_S < 0.25 ABUT< 90 REGION) NOT INSIDE EXCLU
}

SRCK_R_17_AA {
    @ Assembly isolation between active AA/GT/METAL/RDL patterns and internal metal ring edge (including Mn, Top Metal and RDL)>= 11.111um
    (EXT (AA NOT INSIDE MARKS) MS_RING_INNER < 11.111 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

DFM_S_103_V5 {
    @ Space between Vn and unconnected Mn+1 (n = 1,2,3,4,5,6,7)>= 0.12um
    (EXT M6_EMPTY4 V5_EMPTY4 < 0.12 ABUT<90 REGION OPPOSITE MEASURE ALL NOT CONNECTED) NOT INSIDE EXDFM
}

DFM_O_79 {
@ SP and AA overlap >= 0.13um
  (INT SP (AA NOT TOUCH EDGE SP) < 0.13 ABUT<90 REGION) NOT INSIDE EXDFM
}

SRAA_A_8 {
@ AA area >= 0.038 0.029um2
  X = AREA AA < 0.029
  (X NOT OUTSIDE INST) NOT INSIDE EXCLU
}

ESD_S_12_G {
@ Space between active poly gate and inactive poly gate of 1.2V Cascoded NMOS(SGT) (Fig.6) >= 0.6um
EGT = GT AND 1_2V_ESD_CASCODED
ESAB_CASCODED = ESAB AND 1_2V_ESD_CASCODED
((EXT EGT < 0.6 ABUT < 90  OPPOSITE REGION)AND ESAB_CASCODED)NOT EXCLU
}

SL_EN_5_M5_G {
    @ Open slot must be fully enclosed by metal line.>= 2um
    (ENC M5SLOT M5i < 2.0 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
    (M5SLOT NOT M5i) NOT INSIDE EXCLU
}

RESNWST_EN_3a {
@ CT enclosed by silicided AA>= 0.03um
 X = CT AND NWRSTI
 Y = AA INTERACT X
 (ENC X Y < 0.03 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

SRCK_S_41_TV2 {
    @ Space between square TVn (n=1~2) and TMn (n=1~2)/TKM dummy metal edge in the die corner dummy relief area (for 4X option)>= 0.931um
    (ENC TV2S_SQ (TKM AND Die_corner) < 0.931 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

DG_S_9a {
@ Space or extension of DG to NW, set the value to 0 if it is smaller than 0.36um>= 0.36um
  (ENC NW DG > 0 < 0.36 ABUT>0<90 SINGULAR REGION) NOT INSIDE EXCLU
  (EXT NW DG > 0 < 0.36 ABUT>0<90 SINGULAR REGION) NOT INSIDE EXCLU
}

DFM_R_4_V3 {
    @ Insert two Vn (n=1~7) at least. if Mn width>=5M(n+1) width, or M(n+1) width>=5Mn width (when Mn and M(n+1) length>=15um)
    CMACRO DFM4 M3 M4 V3
}

NW_A_8 {
    @ NW area >= 0.3um2
    (AREA NW < 0.3) NOT INSIDE EXCLU
}

V4_S_2a1 {
    @ Space between two Vns >= 0.1um
    (EXT V4 < 0.1 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

PSUB_W_2 {
    @ 1.2/2.5V native NMOS channel width>= 0.5um
    X = LENGTH GATE_W < 0.5
    ((EXPAND EDGE X INSIDE BY 0.001) AND PSUB) NOT INSIDE EXCLU
}

SRCK_S_36_V5 {
    @ Space between square Vn (n=1~7) >= 0.543um
    (EXT V5S_SQ < 0.543 ABUT < 90 SINGULAR REGION) NOT INSIDE EXCLUi
}

SL_R_10_M3_G {
    @ Metal slot must be rectangle.
    (NOT RECTANGLE M3SLOT) NOT INSIDE EXCLU
}

AA_A_8a {
    @ AA area (except the INST region).>= 0.038um2
    ((AREA AA < 0.038) NOT INSIDE INST) NOT INSIDE EXCLU
}

ESD_L_4c_G {
@ Channel length(GTL) of 2.5V overdrive 3.3V NMOS for ESD protection device.>= 0.5um
(LENGTH ((EGATE_2_5V_O_3_3V AND ENACT) COIN EDGE EGATE_L) < 0.5) NOT INSIDE EDGE EXCLU
}

DGR_12 {
@ The layout of designs should not have these layers including PW, PWH, NWH, NC, HR, NLH, PLH, NLL, PLL, ALPA and PA.
  X = COPY DRC:1
  Y = OR PWi PWH NWH NC HR NLH PLH NLL PLL ALPAi PAi
  X AND Y
}

PSUB_A_15_R {
    @ (R) Area when one of the edge length <0.8um>= 0.3um2
    X = LENGTH PSUB < 0.8
    Y = PSUB WITH EDGE X
    (AREA Y < 0.3) NOT INSIDE EXCLU
}

RESNWST_W_1a {
@ NW-Resistor width >= 1.5um
 (LENGTH (NWSTI_resistor INSIDE EDGE NW) < 1.5) NOT INSIDE EDGE EXCLU
}

DFM_EX_70 {
@ SN extension outside of Poly GATE for NMOS along source/drain direction, except the INST region.>= 0.32um
  X = GATE_W INSIDE EDGE SN
  Y = ENC X SN < 0.32 ABUT<90 OPPOSITE REGION
  (Y NOT INSIDE INST) NOT INSIDE EXDFM
}

PSUB_R_11 {
    @ Only one AA pattern is allowed in one PSUB region, except for NMOS capacitors and AAs in INDMY.
    (PSUB INTERACT (AA NOT INTERACT (CAPBP OR INDMY)) > 1) NOT INSIDE EXCLU
}

SAB_EX_8a {
@ Extension of SAB outside of AA>= 0.17um
  (ENC AA SAB < 0.17 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
}

LD_L_1_NOSHR_G {
@ LDMOS gate length >= 0.532um
 ((INT LDNGATE < 0.532 ABUT<90 SINGULAR REGION)NOT OUTSIDE NOSHR) NOT INSIDE EXCLU
 ((INT LDPGATE < 0.532 ABUT<90 SINGULAR REGION)NOT OUTSIDE NOSHR) NOT INSIDE EXCLU
}

SRCK_R_26_M4 {
    @ AA, CT, M1/Mn/Vn/TMn/TKM/TVn/BCB1(RDL via) and RDL layers are must drawn layers in MARKS seal ring region.
    (MARKS NOT ENCLOSE M4) NOT INSIDE EXCLUi
}

DFM_EX_10_V2 {
    @ Mn line-end extension outside of Vn (n = 1,2,3,4,5,6,7)>= 0.04um
    X = CONVEX EDGE M2 ANGLE1 == 90 ANGLE2 == 90 WITH LENGTH <= 0.18 LENGTH1 > 0.18 LENGTH2 > 0.18
    (ENC V2 X < 0.04 OPPOSITE REGION) NOT INSIDE EXDFM
}

DFM_EN_9_V2M2 {
    @ Single Vn enclosure by Mn (n = 2,3,4,5,6,7)>= 0.025um
    X = (M2 AND M3) INTERACT V2 == 1
    Y = X COIN EDGE M2
    (ENC V2 Y < 0.025 ABUT<90 REGION) NOT INSIDE EXDFM
}

SL_W_L_1_2_M2_G {
    @ SL_W_1_G: Slot width >= 0.8um
    @ SL_L_2_G: Slot length >= 1um
    (NOT RECTANGLE M2SLOT >= 0.8 BY >= 1.0) NOT INSIDE EXCLU
}

BCB2_S_2_R_6 {
    @ BCB2_S_2: Space between two BCB2 (suggest to consult with package vendor)>= 5um
    @ BCB2_R_6: DRC allows 0.002um checking tolerance in INDMY region for BCB2.W.1-BCB2.S.4 rules.
    ((EXT BCB2 < 5 ABUT<90 SINGULAR REGION) NOT INDMY) NOT INSIDE EXCLU
    ((EXT BCB2 < 5 - 0.002 ABUT<90 SINGULAR REGION) AND INDMY) NOT INSIDE EXCLU
}

M1DUMCK_S_7 {
    @ Space between dummy metal and LOGO.
    @ Metal dummy pattern insertion is not allowed to touch areas covered by LOGO.>= 0.1um
    (EXT M1DUM LOGO < 0.1 ABUT<90 SINGULAR REGION INSIDE ALSO) NOT INSIDE EXCLU
}

DFM_A_38 {
@ NW area >= 1.2um2
 (AREA NW < 1.2) NOT INSIDE EXDFM
}

PEFU_L_4c_G {
@ Poly EFuse element GT length>= 0.36um
(RECTANGLE EFUSE_element == 0.06 BY < 0.36)NOT EXCLU
}

SL_EN_5_TKM_G {
    @ Open slot must be fully enclosed by metal line.>= 2um
    (ENC TKMSLOT TKMi < 2.0 ABUT<90 SINGULAR REGION) NOT INSIDE EXCLU
    (TKMSLOT NOT TKMi) NOT INSIDE EXCLU
}

SRM1_A_4 {
@ M1 area >= 0.027um2
 X = AREA (M1 OR M1DUM) < 0.027
 (X NOT OUTSIDE INST) NOT INSIDE EXCLU
}

SRCK_R_17_GT {
